/**
 * Build a single self-contained HTML file: dist/marque-points.html
 *
 * The app is normally served over http:// as ES modules. That file instead
 * carries the stylesheet and every module inline, so it opens straight from
 * the disk (file://), can be mailed to the other players, and keeps working
 * offline. Run it with `npm run bundle`.
 *
 * The output is deterministic — same sources in, same bytes out — so a test
 * can check that the committed file is not stale.
 */

import { readFile, writeFile, mkdir } from 'node:fs/promises';
import { join, resolve } from 'node:path';

const root = resolve(import.meta.dirname, '..');

/** Modules in dependency order: each one only uses what comes before it. */
const MODULES = ['i18n.js', 'games.js', 'model.js', 'scoring.js', 'storage.js', 'app.js'];

const IMPORT_LINE = /^import\s.*?;\s*$/gm;
const EXPORT_KEYWORD = /^export\s+(?=(?:const|let|function|class|async)\b)/gm;
/** Top-level declarations, used to catch a name defined by two modules. */
const TOP_LEVEL_DECLARATION = /^(?:const|let|var|function|class)\s+([A-Za-z_$][\w$]*)/gm;

/** Strip a module down to plain script code. */
function toScript(source) {
  return source.replace(IMPORT_LINE, '').replace(EXPORT_KEYWORD, '').trim();
}

export async function bundle() {
  const [html, css] = await Promise.all([
    readFile(join(root, 'index.html'), 'utf8'),
    readFile(join(root, 'styles.css'), 'utf8'),
  ]);

  const declaredIn = new Map();
  const parts = [];

  for (const name of MODULES) {
    const code = toScript(await readFile(join(root, 'src', name), 'utf8'));

    for (const [, identifier] of code.matchAll(TOP_LEVEL_DECLARATION)) {
      const previous = declaredIn.get(identifier);
      if (previous) {
        throw new Error(
          `Cannot bundle: "${identifier}" is declared both in ${previous} and in ${name}. ` +
            'Rename one of them — the bundle puts every module in one scope.',
        );
      }
      declaredIn.set(identifier, name);
    }
    parts.push(`  // ---- src/${name} ${'-'.repeat(Math.max(0, 60 - name.length))}\n${code}`);
  }

  const script = parts.join('\n\n');
  if (/<\/script/i.test(script) || /<\/style/i.test(css)) {
    throw new Error('Cannot bundle: a source file contains a closing script or style tag.');
  }

  // Each substitution must actually fire: a silent no-op would ship a page
  // pointing at files that are not there.
  const substitute = (source, pattern, replacement, what) => {
    const result = source.replace(pattern, replacement);
    if (result === source) {
      throw new Error(`Cannot bundle: index.html has no ${what} to inline any more.`);
    }
    return result;
  };

  let output = substitute(
    html,
    /^([ \t]*)<link rel="stylesheet" href="styles\.css" \/>$/m,
    (_, indent) => `${indent}<style>\n${css.trimEnd()}\n${indent}</style>`,
    'stylesheet link',
  );
  output = substitute(
    output,
    /^([ \t]*)<script type="module" src="src\/app\.js"><\/script>$/m,
    (_, indent) => `${indent}<script>\n(() => {\n${script}\n})();\n${indent}</script>`,
    'module script tag',
  );
  return substitute(
    output,
    '<head>',
    '<head>\n    <!-- Generated by tools/bundle.js — edit the sources, not this file. -->',
    'head tag',
  );
}

// Only write the file when run as a command, not when imported by a test.
if (process.argv[1] && resolve(process.argv[1]) === resolve(import.meta.filename)) {
  const output = await bundle();
  await mkdir(join(root, 'dist'), { recursive: true });
  await writeFile(join(root, 'dist', 'marque-points.html'), output);
  console.log(`dist/marque-points.html — ${(output.length / 1024).toFixed(0)} KB, no dependencies`);
}
